// ⭐ A167 (a)(b)(c)(g) · WHO HAS A PLAN, THE TRIAL OF 10 DRAFTS, AND THE ONE THING THAT IS GATED.
//
// ⛔ (g) THE WHOLE SITE IS OPEN WITHOUT A SUBSCRIPTION. The board, the résumé, Atlas, Learn, the tracker, the editor, a
// résumé generated by hand — all of it. ONLY "Apply through draft" — a SEMI or FULL AUTO run (POST /api/apply/runs, a
// scheduled or Run now batch, a pick's Apply tap) — asks for a plan, and only once the trial's 10 drafts are used.
// `applyAllowed` is that one gate; nothing else in this file blocks anything.
//
// Subscriptions are written ONLY from Stripe's webhooks (verified, services/billing/stripe.js), never from a redirect a
// browser can fake: the success page reads the state, it never sets it. Every event id is recorded once in
// billing_events, so a redelivered event (Stripe retries for days) is a no-op.
import { billingConfig, tierForPrice } from "./config.js";

const now = () => Math.floor(Date.now() / 1000);
// Stripe's statuses that mean "this person is paying" — past_due keeps access while Stripe retries the card.
export const ACTIVE_STATUSES = Object.freeze(["active", "trialing", "past_due"]);

export function customerIdFor(db, userId) {
  return db.prepare("SELECT stripe_customer_id FROM billing_customers WHERE user_id = ?").pluck().get(userId) ?? null;
}
export function saveCustomer(db, userId, customerId, livemode = false) {
  db.prepare(`INSERT INTO billing_customers (user_id, stripe_customer_id, livemode) VALUES (?, ?, ?)
    ON CONFLICT(user_id) DO UPDATE SET stripe_customer_id = excluded.stripe_customer_id, livemode = excluded.livemode`)
    .run(userId, customerId, livemode ? 1 : 0);
}
const userForCustomer = (db, customerId) =>
  db.prepare("SELECT user_id FROM billing_customers WHERE stripe_customer_id = ?").pluck().get(customerId) ?? null;

/** The person's current subscription (the newest active one), or null. */
export function activeSubscription(db, userId) {
  return db.prepare(`SELECT * FROM billing_subscriptions WHERE user_id = ? AND status IN (${ACTIVE_STATUSES.map(() => "?").join(",")})
    ORDER BY updated_at DESC LIMIT 1`).get(userId, ...ACTIVE_STATUSES) ?? null;
}

// ── (c) THE TRIAL: 10 drafts, one per job (a re-draft of the same posting is not another) ───────────────────────────
export function trialUsed(db, userId) {
  return db.prepare("SELECT COUNT(*) FROM trial_drafts WHERE user_id = ?").pluck().get(userId) ?? 0;
}
export function trialLeft(db, userId, env = process.env) {
  return Math.max(0, billingConfig(env).trialDrafts - trialUsed(db, userId));
}
/** Record the drafts a run spends (only the NEW job ids count). Returns how many were new. */
export function spendTrialDrafts(db, userId, jobIds) {
  const ins = db.prepare("INSERT OR IGNORE INTO trial_drafts (user_id, job_id) VALUES (?, ?)");
  let n = 0;
  db.transaction(() => { for (const j of jobIds) n += ins.run(userId, String(j)).changes; })();
  return n;
}

/**
 * ⛔ THE ONE GATE (g): may this person apply through draft for these jobs?
 * @returns {{ ok: true, via: "off"|"plan"|"trial", trialLeft?: number } | { ok: false, code: string, message: string, trialLeft: number }}
 */
export function applyAllowed(db, userId, jobIds = [], env = process.env) {
  const cfg = billingConfig(env);
  if (!cfg.enabled) return { ok: true, via: "off" };
  const sub = activeSubscription(db, userId);
  if (sub) return { ok: true, via: "plan", tier: sub.tier };
  const already = new Set(db.prepare("SELECT job_id FROM trial_drafts WHERE user_id = ?").pluck().all(userId));
  const fresh = [...new Set(jobIds.map(String))].filter(j => !already.has(j));
  const left = Math.max(0, cfg.trialDrafts - already.size);
  if (fresh.length <= left) return { ok: true, via: "trial", trialLeft: left - fresh.length, spend: fresh };
  return {
    ok: false, code: "plan_required", trialLeft: left,
    message: left > 0
      ? `Your trial has ${left} draft${left === 1 ? "" : "s"} left — pick ${left} or fewer, or choose a plan to apply through draft.`
      : "Your 10 trial drafts are used. Choose a plan to keep applying through draft — everything else on the site stays open.",
  };
}

/** What Settings → Plan shows. */
export function billingStatus(db, userId, env = process.env) {
  const cfg = billingConfig(env);
  const sub = cfg.enabled ? activeSubscription(db, userId) : null;
  return {
    enabled: cfg.enabled,
    stripeReady: cfg.stripeReady,
    mode: cfg.stripeMode,
    testPrices: cfg.testPrices,
    trial: { drafts: cfg.trialDrafts, used: trialUsed(db, userId), left: trialLeft(db, userId, env) },
    subscription: sub ? { tier: sub.tier, status: sub.status, renewsAt: sub.current_period_end, cancelAtPeriodEnd: !!sub.cancel_at_period_end } : null,
    tiers: cfg.tiers.map(t => ({ id: t.id, name: t.name, blurb: t.blurb, interval: t.interval, priceCents: t.testPriceCents, available: !!t.priceId })),
    hasCustomer: !!customerIdFor(db, userId),
  };
}

// ── WEBHOOKS ─────────────────────────────────────────────────────────────────────────────────────────────────────────
function upsertSubscription(db, sub, userId, env) {
  const priceId = sub?.items?.data?.[0]?.price?.id ?? null;
  const tier = tierForPrice(priceId, env)?.id || sub?.metadata?.tier || null;
  db.prepare(`INSERT INTO billing_subscriptions (stripe_subscription_id, user_id, tier, price_id, status, current_period_end, cancel_at_period_end, livemode, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(stripe_subscription_id) DO UPDATE SET tier = excluded.tier, price_id = excluded.price_id, status = excluded.status,
      current_period_end = excluded.current_period_end, cancel_at_period_end = excluded.cancel_at_period_end, updated_at = excluded.updated_at`)
    .run(sub.id, userId, tier, priceId, String(sub.status || "incomplete"), Number(sub.current_period_end) || null,
      sub.cancel_at_period_end ? 1 : 0, sub.livemode ? 1 : 0, now());
}

/**
 * Apply ONE verified Stripe event. Idempotent: an event id already processed returns { duplicate: true }.
 * @returns {{ handled: boolean, duplicate?: boolean, userId?: number|null, ignored?: string }}
 */
export function handleStripeEvent(db, event, env = process.env) {
  if (!event?.id || !event?.type) return { handled: false, ignored: "not_an_event" };
  const seen = db.prepare("INSERT OR IGNORE INTO billing_events (stripe_event_id, type, livemode) VALUES (?, ?, ?)")
    .run(event.id, event.type, event.livemode ? 1 : 0);
  if (!seen.changes) {
    const prior = db.prepare("SELECT processed_at FROM billing_events WHERE stripe_event_id = ?").get(event.id);
    if (prior?.processed_at) return { handled: true, duplicate: true };
  }
  const obj = event.data?.object || {};
  let userId = null;
  try {
    switch (event.type) {
      case "checkout.session.completed": {
        userId = Number(obj.client_reference_id || obj.metadata?.user_id) || userForCustomer(db, obj.customer);
        if (userId && obj.customer) saveCustomer(db, userId, obj.customer, !!obj.livemode);
        // The subscription itself arrives as customer.subscription.created; nothing else is trusted from the session.
        break;
      }
      case "customer.subscription.created":
      case "customer.subscription.updated":
      case "customer.subscription.deleted": {
        userId = userForCustomer(db, obj.customer) || Number(obj.metadata?.user_id) || null;
        if (!userId) throw new Error(`no user for customer ${obj.customer}`);
        upsertSubscription(db, event.type === "customer.subscription.deleted" ? { ...obj, status: "canceled" } : obj, userId, env);
        break;
      }
      case "invoice.payment_failed":
      case "invoice.paid":
        // Status changes come through customer.subscription.updated (past_due / active); recorded for the trail only.
        userId = userForCustomer(db, obj.customer);
        break;
      default:
        db.prepare("UPDATE billing_events SET processed_at = ? WHERE stripe_event_id = ?").run(now(), event.id);
        return { handled: false, ignored: event.type };
    }
    db.prepare("UPDATE billing_events SET processed_at = ?, error = NULL WHERE stripe_event_id = ?").run(now(), event.id);
    return { handled: true, userId };
  } catch (e) {
    db.prepare("UPDATE billing_events SET error = ? WHERE stripe_event_id = ?").run(String(e.message).slice(0, 300), event.id);
    throw e;
  }
}
